import {validateRecord} from './room-progress-model.mjs';
const open=()=>new Promise((resolve,reject)=>{const q=indexedDB.open('atlas-room-progress',1);q.onupgradeneeded=()=>{q.result.createObjectStore('rooms',{keyPath:'key'});q.result.createObjectStore('history',{keyPath:'id'});};q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});
export async function readProgress(){const db=await open();try{return await new Promise((resolve,reject)=>{const tx=db.transaction(['rooms','history']),r=tx.objectStore('rooms').getAll(),h=tx.objectStore('history').getAll();tx.oncomplete=()=>resolve({records:r.result,history:h.result});tx.onerror=()=>reject(tx.error);});}finally{db.close();}}
export async function saveProgress(value,expectedVersion){validateRecord(value);if(value.version!==expectedVersion+1)throw Error('Versión inválida');const db=await open();try{await new Promise((resolve,reject)=>{let error;const tx=db.transaction(['rooms','history'],'readwrite'),q=tx.objectStore('rooms').get(value.key);q.onsuccess=()=>{if((q.result?.version||0)!==expectedVersion){error=Error('El recinto cambió en otra pestaña. Conserva tu borrador y vuelve a cargar la ficha antes de guardar.');tx.abort();return;}tx.objectStore('rooms').put(value);tx.objectStore('history').add({id:crypto.randomUUID(),record:value});};tx.oncomplete=resolve;tx.onabort=()=>reject(error||tx.error||Error('No se pudo guardar'));tx.onerror=()=>reject(tx.error);});}finally{db.close();}window.dispatchEvent(new Event('atlas-room-progress-changed'));}
export async function exportProgress(level){const snapshot=await readProgress();return {format:'atlas-room-progress-v1',at:new Date().toISOString(),records:snapshot.records.filter(r=>!level||r.level===level),history:snapshot.history.filter(h=>!level||h.record.level===level)};}
export async function importProgress(value){if(value?.format!=='atlas-room-progress-v1'||!Array.isArray(value.records)||!Array.isArray(value.history))throw Error('Respaldo de avance no válido');value.records.forEach(validateRecord);value.history.forEach(h=>{if(typeof h.id!=='string'||!h.id)throw Error('Historial inválido');validateRecord(h.record);});if(new Set(value.records.map(r=>r.key)).size!==value.records.length||new Set(value.history.map(h=>h.id)).size!==value.history.length)throw Error('Identidades repetidas');const db=await open();try{await new Promise((resolve,reject)=>{let conflict=false;const tx=db.transaction(['rooms','history'],'readwrite');for(const [table,items,id] of [['rooms',value.records,'key'],['history',value.history,'id']])for(const item of items){const q=tx.objectStore(table).get(item[id]);q.onsuccess=()=>{if(q.result&&JSON.stringify(q.result)!==JSON.stringify(item)){conflict=true;tx.abort();return;}if(!q.result)tx.objectStore(table).add(item);};}tx.oncomplete=resolve;tx.onabort=()=>reject(Error(conflict?'Hay registros diferentes en este dispositivo. No se reemplazó ningún avance.':'No se pudo importar'));tx.onerror=()=>reject(tx.error);});}finally{db.close();}window.dispatchEvent(new Event('atlas-room-progress-changed'));}
